Q: Hexadecimal string to byte array in C A: <p>As far as I know, there's no standard function to do so, but it's simple to achieve in the following manner:</p>
<pre><code>#include &lt;stdio.h&gt;

int main(int argc, char **argv) {
    const char hexstring[] = &quot;DEadbeef10203040b00b1e50&quot;, *pos = hexstring;
    unsigned char val[12];

     /* WARNING: no sanitization or error-checking whatsoever */
    for (size_t count = 0; count &lt; sizeof val/sizeof *val; count++) {
        sscanf(pos, &quot;%2hhx&quot;, &amp;val[count]);
        pos += 2;
    }

    printf(&quot;0x&quot;);
    for(size_t count = 0; count &lt; sizeof val/sizeof *val; count++)
        printf(&quot;%02x&quot;, val[count]);
    printf(&quot;\n&quot;);

    return 0;
}
</code></pre>
<hr />
<h3>Edit</h3>
<p>As Al pointed out, in case of an odd number of hex digits in the string, you have to make sure you prefix it with a starting 0. For example, the string <code>&quot;f00f5&quot;</code> will be evaluated as <code>{0xf0, 0x0f, 0x05}</code>  erroneously by the above example, instead of the proper <code>{0x0f, 0x00, 0xf5}</code>.</p>

Q: Unable to transform split string A: <p>If you prefer to work with line in string, then another solution to your problem is to use <code>std::generator</code>. This mixes well with <code>std::from_chars</code>.</p>
<pre class="lang-cpp prettyprint-override"><code>import std;

template &lt;std::integral Int&gt;
auto parse_ints_from(std::string_view in, int base = 10)
    -&gt; std::generator&lt;Int&gt; {
    auto b = in.data();
    auto e = b + in.size();
    while (b != e) {
        while (b != e &amp;&amp; std::isspace(*b)) {
            ++b;
        }
        if (b == e) {
            break;
        }

        Int result = 0;
        auto [ptr, ec] = std::from_chars(b, e, result, base);
        if (ec != std::errc{}) {
            throw std::system_error{std::make_error_code(ec)};
        }
        co_yield result;
        b = ptr;
    }
}

int main() {
    std::string line;
    while (getline(std::cin, line)) {
        try {
            auto v =
                parse_ints_from&lt;int&gt;(line) | std::ranges::to&lt;std::vector&gt;();
            std::println(&quot;v = {}&quot;, v);

        } catch (const std::exception&amp; e) {
            std::println(&quot;Exception: {}&quot;, e.what());
        }
    }
}
</code></pre>
